function validate([words, k]) {
  if (words.length < 1 || words.length > 100000) return 'words needs 1 to 100,000 strings.';
  let total = 0;
  for (const word of words) {
    if (word.length < 1 || word.length > 10000) return 'Each word has 1 to 10,000 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase English letters only.';
    total += word.length;
  }
  if (total > 100000) return 'The words have at most 100,000 letters in total.';
  if (k < 1 || k > words.length) return 'k is between 1 and words.length.';
  return null;
}

