function longestCommonPrefix(words, k) {
  const root = { count: 0, children: new Map() };
  const eligible = [0];
  let deepest = 0;
  for (const word of words) {
    let node = root;
    for (let depth = 1; depth <= word.length; depth++) {
      const letter = word[depth - 1];
      if (!node.children.has(letter)) {
        node.children.set(letter, { count: 0, children: new Map() });
      }
      node = node.children.get(letter);
      node.count++;
      if (node.count === k) {
        eligible[depth] = (eligible[depth] ?? 0) + 1;
        deepest = Math.max(deepest, depth);
      }
    }
  }
  const answer = [];
  for (const word of words) {
    let best = deepest;
    let node = root;
    for (let depth = 1; depth <= word.length; depth++) {
      node = node.children.get(word[depth - 1]);
      if (node.count === k && eligible[depth] === 1) {
        best = depth - 1;
        break;
      }
    }
    answer.push(best);
  }
  return answer;
}

