function longestCommonPrefix(words, k) {
  // Remove each word in turn and count every prefix of the words that remain.
  return words.map((_, removed) => {
    const counts = new Map();
    let best = 0;
    words.forEach((word, j) => {
      if (j === removed) return;
      for (let length = 1; length <= word.length; length++) {
        const prefix = word.slice(0, length);
        const seen = (counts.get(prefix) ?? 0) + 1;
        counts.set(prefix, seen);
        if (seen >= k) best = Math.max(best, length);
      }
    });
    return best;
  });
}

