function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Few letters make shared prefixes and repeated words common.
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, rand() < 0.75 ? int(1, 3) : 26);
  const randomWord = length => Array.from({ length }, () => letters[int(0, letters.length - 1)]).join('');
  const smallK = n => rand() < 0.2 ? n : int(1, Math.min(n, 4));
  if (size === 'small') {
    const n = int(1, 7);
    const words = Array.from({ length: n }, () => randomWord(int(1, 5)));
    return [words, smallK(n)];
  }
  if (rand() < 0.5) {
    // Many short words, and k of them share one long planted prefix, so removing those k changes the answer.
    const words = Array.from({ length: 2000 }, () => randomWord(int(1, 12)));
    const k = rand() < 0.2 ? int(100, 2000) : int(2, 6);
    const planted = randomWord(int(20, 40));
    const chosen = new Set();
    while (chosen.size < Math.min(k, 6)) chosen.add(int(0, 1999));
    for (const index of chosen) words[index] = planted + randomWord(int(0, 5));
    return [words, k];
  }
  // A few long words that follow one base string for a while and then branch off; some are repeated.
  const base = randomWord(10000);
  const words = [];
  const n = int(4, 9);
  while (words.length < n) {
    if (words.length && rand() < 0.3) {
      words.push(words[int(0, words.length - 1)]);
      continue;
    }
    const shared = int(1, 9990);
    const word = base.slice(0, shared) + randomWord(int(0, 10));
    words.push(word.slice(0, 10000));
  }
  return [words, int(1, Math.min(n - 1, 4))];
}
